import {ENV_DEFAULTS,DEFAULT_MOONS,MAX_MOONS,environmentSettings,environmentLight} from './environment.mjs';
export function syncEnvironmentUI(map,change){const body=document.querySelector('#lightPanel .panelbody');if(!body)return;let root=document.getElementById('environmentSettings');if(!root){root=document.createElement('section');root.id='environmentSettings';root.innerHTML=`<h3>Ciel, saisons et météo</h3><label class="check"><input id="env-enabled" type="checkbox">Activer le ciel</label><label>Heure du jour<input id="env-hour" type="range" min="0" max="24" step="0.25"></label><div class="row"><label>Zénith<input id="env-zenith" type="color"></label><label>Horizon<input id="env-horizon" type="color"></label><label>Nuages<input id="env-cloudColor" type="color"></label></div><label>Couverture nuageuse<input id="env-clouds" type="range" min="0" max="1" step="0.05"></label><label>Altitude des nuages<input id="env-cloudHeight" type="number" min="20" max="100" step="1"></label><label>Vent<input id="env-wind" type="range" min="0" max="2" step="0.05"></label><label>Nuages volumétriques<select id="env-quality"><option value="off">Désactivés</option><option value="low">Légers · 8 étapes</option><option value="balanced">Équilibrés · 12 étapes</option><option value="high">Détaillés · 24 étapes</option></select></label><label class="check"><input id="env-cloudShadows" type="checkbox">Ombres des nuages volumétriques</label><label>Force des ombres de nuages<input id="env-cloudShadowStrength" type="range" min="0" max="0.6" step="0.05"></label><h3>Ciel nocturne</h3><label class="check"><input id="env-stars" type="checkbox">Afficher les étoiles la nuit</label><label>Densité des étoiles<input id="env-starDensity" type="range" min="0" max="1" step="0.05"></label><h3>Lunes et anneaux</h3><p class="micro">Ajoute jusqu’à quatre lunes, avec une taille, une phase, une orbite et des anneaux indépendants. La lune principale apparaît la nuit, à l’opposé du soleil.</p><div id="env-moons"></div><button type="button" id="env-addMoon">+ Ajouter une lune</button><label>Saison<select id="env-season"><option value="spring">Printemps</option><option value="summer">Été</option><option value="autumn">Automne</option><option value="winter">Hiver</option></select></label><label>Météo<select id="env-weather"><option value="clear">Temps sec</option><option value="rain">Pluie</option><option value="snow">Neige</option></select></label><label>Intensité des précipitations<input id="env-intensity" type="range" min="0" max="1" step="0.05"></label><label class="check"><input id="env-syncLight" type="checkbox">Lier l’éclairage à l’heure et à la météo</label><p class="micro">Les saisons changent la teinte du sol. La météo est locale à la caméra ; la neige ne modifie pas les collisions. Les nuages détaillés coûtent davantage de calculs. Les ombres de nuages ajoutent une variation lumineuse projetée sur le terrain et les blocs.</p><h3>Distance de rendu</h3><p class="micro">Deux chunks autour de la caméra, prolongés par un cône devant elle. Les collisions et la vision des personnages restent calculées indépendamment.</p><label>Distance devant (cases)<input id="render-far" type="range" min="48" max="144" step="16"></label><label>Ouverture du cône (°)<input id="render-cone" type="range" min="70" max="160" step="10"></label><label>Budget des effets<select id="render-effects"><option value="low">Léger</option><option value="balanced">Équilibré</option><option value="high">Détaillé</option></select></label><label>Qualité des textures<select id="render-surface"><option value="detail">Détaillée · rotations et raccords</option><option value="fast">Fluide · échantillon simple</option></select></label><p class="micro">Objets 3D : Kenney, CC0. Effets : Three.quarks, MIT.</p>`;body.prepend(root)}let e=environmentSettings(map);for(const k of Object.keys(ENV_DEFAULTS)){if(k==='moons')continue;const el=document.getElementById('env-'+k);if(!el)continue;el.type==='checkbox'?el.checked=e[k]:el.value=e[k];el.onchange=()=>change(()=>{map.environment??={...ENV_DEFAULTS};map.environment[k]=el.type==='checkbox'?el.checked:typeof ENV_DEFAULTS[k]==='number'?Number(el.value):el.value;if(map.environment.enabled&&map.environment.syncLight){let l=environmentLight(map.environment);map.lighting.ambient=l.ambient;map.lighting.sunAngle=l.angle;map.lighting.sunPower=l.sun*.65}})}for(const k of ['far','cone','effects','surface']){let el=document.getElementById('render-'+k);el.value=map.renderSettings?.[k]??({far:80,cone:110,effects:'balanced',surface:'detail'}[k]);el.onchange=()=>change(()=>{map.renderSettings??={};map.renderSettings[k]=k==='effects'||k==='surface'?el.value:Number(el.value)})}
 const moonContainer=document.getElementById('env-moons');if(!moonContainer)return;
 const moons=Array.isArray(map.environment?.moons)?map.environment.moons:e.moons;
 moonContainer.replaceChildren();
 const fields=[['name','Nom','text'],['color','Couleur','color'],['size','Taille (°)','number',.3,6,.1],['phase','Phase (0 à 1)','number',0,1,.05],['orbitOffset','Décalage orbital (°)','number',-180,180,5],['ring','Anneaux','checkbox'],['ringColor','Teinte des anneaux','color'],['ringWidth','Largeur des anneaux','number',.1,2,.1],['ringTilt','Inclinaison des anneaux (°)','number',-180,180,5]];
 const moonFallback={...DEFAULT_MOONS[0]};
 moons.slice(0,MAX_MOONS).forEach((moon,index)=>{
  const fieldset=document.createElement('fieldset');fieldset.className='env-moon-config';
  const legend=document.createElement('legend');legend.textContent=(moon.name||'Lune')+' · '+(index+1);fieldset.append(legend);
  for(const [prop,title,type,min,max,step] of fields){
   const label=document.createElement('label');label.textContent=title;
   const input=document.createElement('input');input.type=type;input.value=moon[prop]??moonFallback[prop]??'';
   if(type==='checkbox')input.checked=!!moon[prop];
   if(min!==undefined){input.min=min;input.max=max;input.step=step;}
   input.onchange=()=>change(()=>{map.environment??={...ENV_DEFAULTS};map.environment.moons=[...moons].map(v=>({...v}));map.environment.moons[index][prop]=type==='checkbox'?input.checked:type==='number'?Number(input.value):input.value;});
   label.append(input);fieldset.append(label);
  }
  const remove=document.createElement('button');remove.type='button';remove.textContent='Supprimer cette lune';remove.onclick=()=>change(()=>{map.environment??={...ENV_DEFAULTS};map.environment.moons=moons.filter((_,i)=>i!==index);});fieldset.append(remove);
  moonContainer.append(fieldset);
 });
 const add=document.getElementById('env-addMoon');add.disabled=moons.length>=MAX_MOONS;
 add.onclick=()=>change(()=>{map.environment??={...ENV_DEFAULTS};map.environment.moons=[...moons,{...DEFAULT_MOONS[0],name:'Lune '+(moons.length+1),orbitOffset:moons.length*35,color:moons.length%2?'#ffd9ab':'#d3e7ff'}].slice(0,MAX_MOONS);});
}
